import json, sys, time, urllib.request, urllib.error
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from email.utils import parsedate_to_datetime

BASE = 'http://localhost:8080'
token = None

def wait_seconds(value):
    if not value:
        return 1.0
    try:
        return max(0.0, float(value))
    except ValueError:
        try:
            return max(0.0, (parsedate_to_datetime(value) - datetime.now(timezone.utc)).total_seconds())
        except (ValueError, TypeError):
            return 1.0

def request(path, method='GET', auth=True):
    global token
    for attempt in range(100):
        if auth and token is None:
            token = [REDACTED_SECRET]'/token', 'POST', False)['token']
        headers = {'Authorization': 'Bearer ' + token} if auth else {}
        req = urllib.request.Request(BASE + path, headers=headers, method=method)
        try:
            with urllib.request.urlopen(req, timeout=30) as response:
                return json.load(response)
        except urllib.error.HTTPError as exc:
            if exc.code == 401 and auth:
                token = None
                continue
            if exc.code == 429:
                delay = wait_seconds(exc.headers.get('Retry-After'))
                print(f'429 {path}, waiting {delay}s', file=sys.stderr, flush=True)
                time.sleep(delay)
                continue
            if exc.code in (500, 502, 503, 504):
                time.sleep(min(2 ** min(attempt, 5), 30))
                continue
            raise
        except (urllib.error.URLError, TimeoutError, ConnectionError):
            time.sleep(min(2 ** min(attempt, 5), 30))
    raise RuntimeError(f'Retries exhausted: {path}')

start = datetime(2025, 3, 1, tzinfo=timezone.utc)
end = datetime(2025, 6, 1, tzinfo=timezone.utc)
seen = set()
duplicates = 0
qualifying = []
page = 1
while True:
    data = request(f'/orders?page={page}')
    assert data['page'] == page, (page, data['page'])
    total_pages = data['total_pages']
    for order in data['items']:
        oid = order['id']
        if oid in seen:
            duplicates += 1
            continue
        seen.add(oid)
        dt = datetime.fromisoformat(order['placed_at'].replace('Z', '+00:00')).astimezone(timezone.utc)
        if order['status'] == 'shipped' and start <= dt < end:
            qualifying.append(order)
    print(f'page {page}/{total_pages}, unique {len(seen)}, qualifying {len(qualifying)}, duplicates {duplicates}', file=sys.stderr, flush=True)
    nxt = data['next']
    if page == total_pages:
        assert nxt is None, (page, nxt)
        break
    assert nxt == f'/orders?page={page+1}', (page, nxt)
    page += 1

customers = {}
by_region = dict.fromkeys(('north', 'south', 'east', 'west'), 0)
for i, order in enumerate(qualifying, 1):
    cid = order['customer_id']
    if cid not in customers:
        customers[cid] = request(f'/customers/{cid}')
    customer = customers[cid]
    assert customer['id'] == cid, (cid, customer['id'])
    amount = Decimal(order['amount_cents']) * (Decimal(100) - Decimal(customer['discount_pct'])) / Decimal(100)
    cents = int(amount.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
    by_region[customer['region']] += cents
    if i % 100 == 0:
        print(f'processed {i}/{len(qualifying)} orders; {len(customers)} customers', file=sys.stderr, flush=True)

result = {'total_cents': sum(by_region.values()), 'order_count': len(qualifying), 'duplicates_skipped': duplicates, 'by_region': by_region}
with open('/workspace/result.json', 'w') as f:
    json.dump(result, f, indent=2)
    f.write('\\n')
print(json.dumps(result, indent=2))
